def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def segments(length, divs):
        result, start = [], 0
        for p in divs:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < length:
            result.append((start, length))
        return result

    row_segs = segments(h, div_rows)
    col_segs = segments(w, div_cols)

    blocks = []
    for ri, (r0, r1) in enumerate(row_segs):
        for ci, (c0, c1) in enumerate(col_segs):
            count = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            blocks.append((count, ri, ci))

    _, sri, sci = max(blocks)
    sr0, sr1 = row_segs[sri]
    sc0, sc1 = col_segs[sci]
    source = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1 in row_segs:
        for c0, c1 in col_segs:
            if r1 - r0 == len(source) and c1 - c0 == len(source[0]):
                for dr in range(len(source)):
                    for dc in range(len(source[0])):
                        out[r0 + dr][c0 + dc] = source[dr][dc]
    return out
